func testRemessaBancariumToOnePortadorUsingPor(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local RemessaBancarium
	var foreign Portador

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, remessaBancariumDBTypes, false, remessaBancariumColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize RemessaBancarium struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, portadorDBTypes, false, portadorColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Portador struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.PorID = foreign.PorID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Por().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.PorID != foreign.PorID {
		t.Errorf("want: %v, got %v", foreign.PorID, check.PorID)
	}

	ranAfterSelectHook := false
	AddPortadorHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Portador) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := RemessaBancariumSlice{&local}
	if err = local.L.LoadPor(ctx, tx, false, (*[]*RemessaBancarium)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Por == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Por = nil
	if err = local.L.LoadPor(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Por == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

